insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('maddison-2023', 'Maddison Project, Groningen Growth and Development Centre (University of Groningen)', 'Maddison Project Database 2023 (Bolt and van Zanden, 2024)', 'https://doi.org/10.34894/INZBF2', 'C', 'CC BY 4.0', 'Historical GDP per capita in 2011 international dollars (PPP), compiled from national accounts and academic reconstructions. India before 1947: Broadberry, Custodis and Gupta (2015) for 1600-1871; Heston (1983) for 1870-1900; Maddison (1985) for 1900-46 (per the file''s Sources sheets).', 'India, 152 values, 1600-2022', 'Long-run estimates carry wide uncertainty before 1950; benchmark years are not annual data. Cite: Bolt, J. and van Zanden, J.L. (2024), Journal of Economic Surveys, doi:10.1111/joes.12618.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nfhs5-compendium-phase1', 'IIPS / Ministry of Health and Family Welfare (copy hosted by MoHFW National Health Mission)', 'NFHS-5 State Factsheet Compendium, Phase I (22 states/UTs)', 'https://nhm.gov.in/uhc-day/Session%202/NFHS-5%20State%20Factsheet%20Compendium_Phase-I%20(1).pdf', 'A', 'Government of India publication', 'Household survey; fact sheets print NFHS-5 (2019-20) and NFHS-4 (2015-16) side by side.', '22 states/UTs', 'Provisional fact-sheet results; survey estimates with sampling error.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
